// Learning baseline. Small static state; NOT an atomic concurrency-safe ledger.
const b=$json.body||{};
if(b.lab!=='operantsolo-fictional-v1') return [{json:{httpStatus:400,decision:'reject',reason:'fictional_lab_only'}}];
const s=$getWorkflowStaticData('global');s.runs=s.runs||{};
if(typeof b.runId!=='string'||!/^[a-z0-9-]{1,40}$/.test(b.runId)) return [{json:{httpStatus:400,decision:'reject',reason:'invalid_run_id'}}];
if(!s.runs[b.runId]){if(Object.keys(s.runs).length>=20)return [{json:{httpStatus:429,decision:'reject',reason:'lab_state_limit'}}];s.runs[b.runId]={events:{},entities:{},actions:0};}
const r=s.runs[b.runId];
const out=(httpStatus,decision,extra={})=>[{json:{httpStatus,decision,actions:r.actions,runId:b.runId,eventId:b.eventId||null,executionId:$execution.id,...extra}}];
if(typeof b.eventId!=='string'||!/^evt-[a-z0-9-]{1,30}$/.test(b.eventId)||typeof b.entityId!=='string'||!/^demo-[a-z0-9-]{1,30}$/.test(b.entityId)||!Number.isInteger(b.version)||b.version<1)return out(400,'reject');
const old=r.events[b.eventId];
if(old){if(old.entityId!==b.entityId||old.version!==b.version)return out(409,'conflict');if(old.status==='review'){if(b.reconcile===true){old.status='complete';return out(200,'reconciled');}return out(202,'review');}return out(200,'duplicate');}
if(Object.keys(r.events).length>=100)return out(429,'reject',{reason:'event_limit'});
if(b.version<=(r.entities[b.entityId]||0)){r.events[b.eventId]={entityId:b.entityId,version:b.version,status:'stale'};return out(200,'stale');}
if(b.scenario==='rate_limit'&&b.attempt===1)return out(429,'retry',{retryAfter:1});
if(b.scenario==='unavailable'&&b.attempt===1)return out(503,'retry',{retryAfter:1});
if(b.attempt>3)return out(422,'stop');
r.actions++;r.entities[b.entityId]=b.version;r.events[b.eventId]={entityId:b.entityId,version:b.version,status:b.scenario==='ambiguous'?'review':'complete'};
return out(b.scenario==='ambiguous'?202:200,b.scenario==='ambiguous'?'review':'applied',{note:'Action is a fictional counter, not a real API call'});
